import {cloneElement,isValidElement,useEffect,useState} from 'react';
import {data,confirmed,score,scoreP2,entity,componentsFor,actionFloor,interval,one,scenarios,matches,GATES,ACTION_STATES,SEED_ACTION} from '@/lib/model';
import {Icon,PortfolioVisual,ScoreRibbon,IndicatorBreakdown,NetworkLayers} from '@/components/visuals';
type RecordValue=Record<string,any>;
const views=['Overview','Network','Risk','Alerts','Alternatives','Actions','Evidence','Validation'] as const;
const subtitle:Record<string,string>={Overview:'Decide where continuity evidence is needed first.',Network:'Trace confirmed paths and inspect the source behind each relationship.',Risk:'Reproduce the P3 screen from unrounded case inputs.',Alerts:'Match the right entity, site, role and date before acting.',Alternatives:'Compare like supply forms, then verify independent capacity.',Actions:'Assign, revisit and document continuity decisions.',Evidence:'Keep case records and dated public research within reach.',Validation:'Observe the behaviour of this P3 build and record the result.'};
