const urgency:Record<string,string>={'EV-001':'U2','EV-002':'U0','EV-003':'U2','EV-004':'U0','EV-005':'U0','EV-007':'U0','EV-009':'U0','EV-010':'U3'};
const routeNames=[...new Set(data.candidates.map((c:any)=>c.route))] as string[];
const exportJson=(name:string,value:any)=>{const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function Pill({children,tone='neutral'}:{children:React.ReactNode,tone?:string}){return <span className={'pill '+tone}>{children}</span>}
function Panel({title,detail,children,action}:{title:string,detail?:string,children:React.ReactNode,action?:React.ReactNode}){return <section className="panel"><div className="panel-head"><div><h2>{title}</h2>{detail&&<p>{detail}</p>}</div>{action}</div>{children}</section>}
function Table({heads,rows,empty='No matching records.'}:{heads:string[],rows:React.ReactNode[][],empty?:string}){return <div className="table-scroll"><table><thead><tr>{heads.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length?rows.map((r,i)=><tr key={i}>{r.map((c,j)=><td key={j}>{c}</td>)}</tr>):<tr><td colSpan={heads.length} className="muted">{empty}</td></tr>}</tbody></table></div>}
function Select({label,value,options,onChange}:{label:string,value:string,options:(string|{value:string,label:string})[],onChange:(v:string)=>void}){return <label className="select-label"><span className="sr-only">{label}</span><select aria-label={label} value={value} onChange={e=>onChange(e.target.value)}>{options.map(o=>{const x=typeof o==='string'?{value:o,label:o}:o;return <option value={x.value} key={x.value}>{x.label}</option>})}</select></label>}
function Field({label,children}:{label:string,children:React.ReactNode}){const item=isValidElement(children)&&children.props&&typeof children.props==='object'?children as React.ReactElement<any>:null;const input=item?.props?.type==='date'?cloneElement(item,{onInput:(e:any)=>item.props.onChange?.(e),onBlur:(e:any)=>item.props.onChange?.(e)}):children;return <label className="field"><span>{label}</span>{input}</label>}
const changed=(e:any)=>e instanceof Error?e.message:'Save failed.';
export default function Dashboard({canEdit}:{canEdit:boolean}){
  const [view,setView]=useState<string>('Overview'),[filters,setFilters]=useState({product:'all',component:'all',tier:'all',zone:'all',search:''}),[scenario,setScenario]=useState('Base'),[records,setRecords]=useState<RecordValue[]>([]),[history,setHistory]=useState<RecordValue[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[detail,setDetail]=useState<{type:string,id:string}|null>(null),[menu,setMenu]=useState(false),[trace,setTrace]=useState(''),[overlays,setOverlays]=useState({ownership:false,provisional:false,hypothesis:false}),[route,setRoute]=useState('SiC bare die'),[selected,setSelected]=useState<string[]>([]),[action,setAction]=useState<RecordValue|null>(null),[reference,setReference]=useState<RecordValue|null>(null);
  const load=async()=>{try{const r=await fetch('/api/workspace',{cache:'no-store'});const v=await r.json();if(!r.ok)throw new Error(v.error);setRecords(v.records);setHistory(v.history);setError('')}catch(e){setError(changed(e))}finally{setLoading(false)}};
  useEffect(()=>{load();const hash=()=>{const name=views.find(v=>v.toLowerCase()===location.hash.slice(1));if(name)setView(name)};hash();window.addEventListener('hashchange',hash);return()=>window.removeEventListener('hashchange',hash)},[]);
  useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(id)},[toast]);
  const navigate=(name:string)=>{setView(name);setMenu(false);setDetail(null);historyReplace('#'+name.toLowerCase());window.scrollTo(0,0)};
  const save=async(kind:string,payload:RecordValue)=>{if(!canEdit)throw new Error('Sign in as an editor to save changes.');const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,payload})});const v=await r.json();if(!r.ok)throw new Error(v.error);setRecords(old=>[v,...old.filter(x=>!(x.kind===kind&&x.id===v.id))]);setToast('Saved to workspace');await load();return v};
  const currentModels=records.filter(r=>r.kind==='models');const allScenarios={...scenarios,...Object.fromEntries(currentModels.map(r=>[r.name,{c:r.c,p:r.p}]))};
  const filtered=confirmed.filter((e:any)=>matches(e,filters));const focus=trace?entity(trace):null;
  const exportView=()=>exportJson('novadrive-'+view.toLowerCase()+'-p3.json',{caseDate:data.meta.caseDate,researchDate:data.meta.researchDate,model:data.meta.modelVersion,scenario,assumptions:['Planned allocations are award shares, not purchases or capacity.','E is maximum downstream path exposure, not upstream supply share.','P3 is a screening index, not probability or loss.','Financial inputs for five Tier-3 manufacturers are missing.'],view,filters,manufacturers:filtered.map((e:any)=>({id:e.id,name:e.name,confidence:{link:e.linkConfidence,indicators:e.indicatorConfidence},...score(e,scenario,(allScenarios as any)[scenario])})),events:data.events.map((e:any)=>({id:e.id,urgency:urgency[e.id],disposition:e.disposition})),actions:records.filter(r=>r.kind==='actions'),reviews:records.filter(r=>r.kind==='alerts'),approvals:records.filter(r=>r.kind==='approvals'),research:records.filter(r=>r.kind==='research'),sourceRegister:{retrievedAt:data.meta.researchDate,rows:data.sources.map((s:any)=>({id:s.id,section:s.section,name:s.name,route:s.route,claim:s.claim,urls:s.links.map((l:any)=>l.url)}))},retrievedAt:new Date().toISOString()});
  const openSource=async(id:string)=>{try{const r=await fetch('/api/reference?id='+encodeURIComponent(id));const v=await r.json();if(!r.ok)throw new Error(v.error);setReference(v)}catch(e){setToast(changed(e))}};
  return <div className="shell">
    <aside className={'side '+(menu?'mobile-open':'')}><div className="brand"><div className="brand-mark">N</div><div><strong>NOVADRIVE</strong><small>CONTINUITY</small></div></div><div className="nav-label">WORKSPACE</div><nav aria-label="Workspace">{views.map((name,i)=><button key={name} className={view===name?'active':''} onClick={()=>navigate(name)}><span className="nav-icon"><Icon name={name}/></span>{name}{name==='Alerts'&&<em>2</em>}</button>)}</nav><div className="side-foot"><strong>P3</strong><span>Downstream path exposure</span><small>Case · 30 Sep 2025<br/>Research · 5 Oct 2026</small></div></aside>
    {menu&&<button className="backdrop" aria-label="Close menu" onClick={()=>setMenu(false)}/>}
    <div className="workspace"><header className="top"><button className="menu-toggle" aria-label="Open menu" onClick={()=>setMenu(true)}>☰</button><span>Workspace <b>/</b> {view}</span><div className="top-right"><span className="case-pill">CASE SNAPSHOT</span><span>30 Sep 2025</span><span className="top-divider"/><span>Research · 5 Oct 2026</span></div></header>
      <main><div className="page-head"><div><div className="eyebrow">SUPPLIER CONTINUITY / P3</div><h1>{view==='Overview'?'Portfolio overview':view==='Network'?'Supply network':view==='Risk'?'Supplier priorities':view==='Alerts'?'Event review queue':view==='Alternatives'?'Independent sourcing':view==='Actions'?'Continuity actions':view==='Evidence'?'Evidence & research':'Model & validation'}</h1><p>{subtitle[view]}</p></div><div className="page-actions">{!canEdit&&<a className="button editor-link" href="/editor">Editor sign-in</a>}<button className="button export-button" aria-label="Export decision record" onClick={exportView}><Icon name="Export" size={16}/><span>Export decision record</span></button></div></div>
      {!canEdit&&<p className="viewer-note">Public view · Sign in as an editor to save reviews, actions and validation results.</p>}
      <ScoreRibbon/>
      {error&&<div className="notice warning" role="alert">{error}<button className="link-button" onClick={load}>Retry</button></div>}
      {['Overview','Network','Risk'].includes(view)&&<div className="filters"><Select label="Product" value={filters.product} onChange={product=>setFilters({...filters,product})} options={[{value:'all',label:'All products'},...data.products.map((p:any)=>({value:p.id,label:p.id+' · '+p.name.split(' ')[0]}))]}/><Select label="Component" value={filters.component} onChange={component=>setFilters({...filters,component})} options={[{value:'all',label:'All components'},...data.components.map((c:any)=>({value:c.id,label:c.id+' · '+c.name}))]}/><Select label="Tier" value={filters.tier} onChange={tier=>setFilters({...filters,tier})} options={[{value:'all',label:'All tiers'},...['1','2','3'].map(t=>({value:t,label:'Tier '+t}))]}/><Select label="Zone" value={filters.zone} onChange={zone=>setFilters({...filters,zone})} options={[{value:'all',label:'All zones'},...([...new Set(data.entities.map((e:any)=>e.zone))] as string[]).sort()]}/><input className="search" aria-label="Search manufacturers" placeholder="Search name, ID or site" value={filters.search} onChange={e=>setFilters({...filters,search:e.target.value})}/></div>}
      {view==='Overview'&&<Overview filtered={filtered} open={setDetail} navigate={navigate} trace={(id:string)=>{setTrace(id);navigate('Network')}}/>}
      {view==='Network'&&<Network filtered={filtered} focus={focus} trace={trace} setTrace={setTrace} overlays={overlays} setOverlays={setOverlays} open={setDetail}/>}
      {view==='Risk'&&<Risk filtered={filtered} scenario={scenario} setScenario={setScenario} allScenarios={allScenarios} open={setDetail} openSource={openSource}/>}
      {view==='Alerts'&&<Alerts records={records} open={setDetail}/>}
      {view==='Alternatives'&&<Alternatives route={route} setRoute={setRoute} selected={selected} setSelected={setSelected} records={records} open={setDetail} openSource={openSource}/>}
      {view==='Actions'&&<Actions records={records} history={history} edit={setAction}/>}
      {view==='Evidence'&&<Evidence records={records} save={save} open={setDetail} openSource={openSource}/>}
      {view==='Validation'&&<Validation records={records} history={history} save={save} openSource={openSource}/>}
      <footer>NovaDrive · Consularium / Team Eternal <span>{loading?'Loading saved records…':'P3 · downstream path exposure'}</span></footer></main>
    </div>
    {detail&&<Detail key={detail.type+detail.id} item={detail} close={()=>setDetail(null)} setDetail={setDetail} records={records} save={save} createAction={(draft:any)=>{setDetail(null);setAction(draft);navigate('Actions')}} trace={(id:string)=>{setTrace(id);navigate('Network')}} route={(name:string)=>{setRoute(name);navigate('Alternatives')}}/>}
    {action&&<ActionDialog draft={action} close={()=>setAction(null)} save={save}/>}
    {reference&&<div className="drawer-backdrop" onClick={()=>setReference(null)}><aside className="drawer" onClick={e=>e.stopPropagation()}><div className="drawer-top"><span>ORIGINAL SOLUTION · {reference.id}</span><button aria-label="Close reference" onClick={()=>setReference(null)}>×</button></div><h2>{reference.title}</h2><pre className="source-text">{reference.body}</pre></aside></div>}
    {toast&&<div className="toast" role="status">{toast}</div>}
  </div>;
}
function historyReplace(hash:string){window.history.replaceState(null,'',hash)}

function Overview({filtered,open,navigate,trace}:{filtered:any[],open:(v:any)=>void,navigate:(v:string)=>void,trace:(id:string)=>void}){
  const ranked=filtered.filter(e=>!score(e).missing).sort((a,b)=>score(b).P[0]-score(a).P[0]).slice(0,6);
  return <><div className="metrics"><div><small>Portfolio annual revenue association</small><strong>$1,560m</strong><span>Full portfolio · deduplicated</span></div><div><small>Confirmed manufacturers</small><strong>{filtered.length}</strong><span>8 / 10 / 5 in full network</span></div><div><small>Confirmed supply links</small><strong>29</strong><span>Full network · ten allocations separate</span></div><div><small>Portfolio financial input coverage</small><strong>78.3%</strong><span>18 of 23 manufacturers</span></div></div>
    <PortfolioVisual filtered={filtered} open={open} navigate={navigate}/><div className="section-title"><h2>Priority reviews</h2><small>Event urgency remains separate from the P3 screen</small></div>
    <div className="review-grid"><article className="review-card emphasis"><div className="card-top"><Pill tone="amber">U2 · first continuity review</Pill><span>EV-003</span></div><h3>Meridian financing pressure</h3><p>Covenant negotiations and delayed creditor payments intersect the sole disclosed C20 award. Production continues; verify usable coverage and recovery.</p><div className="path">Meridian <b>→</b> Delta <b>→</b> C20 <b>→</b> P1 / P2</div><div className="card-bottom"><div><strong>$1,144m</strong><small>Associated annual revenue</small></div><button className="primary" onClick={()=>open({type:'alert',id:'EV-003'})}>Review concern</button></div></article>
      <article className="review-card"><div className="card-top"><Pill tone="amber">U2 · site verification</Pill><span>EV-001</span></div><h3>East Delta flood watch</h3><p>IonPeak, Jade, Orion and Umber manufacture in Z01. The case does not establish damage or shutdown at any site.</p><div className="path">Four sites <b>·</b> all three products</div><div className="card-bottom"><div><strong>$1,560m</strong><small>Counted once across products</small></div><button className="button" onClick={()=>open({type:'alert',id:'EV-001'})}>Inspect concern</button></div></article></div>
    <div className="slim-notice"><strong>Gulf Arc port congestion</strong><span>Verify the specific booking before assigning shipment impact.</span><button className="link-button" onClick={()=>open({type:'alert',id:'EV-010'})}>Verify shipment →</button></div>
    <div className="two-cols"><Panel title="Supplier priorities" detail="P3 base screen · complete financial inputs" action={<button className="link-button" onClick={()=>navigate('Risk')}>View all →</button>}><Table heads={['Manufacturer','Reach','P3','Action']} rows={ranked.map(e=>{const s=score(e);return [<button className="text-link" onClick={()=>open({type:'entity',id:e.id})}>{e.short}<small>Tier {e.tier} · {e.zone}</small></button>,e.products.join(' / '),<strong>{interval(s.P)}</strong>,s.band]})}/></Panel>
      <Panel title="Shared constraints" detail="A second supplier name does not establish independence"><div className="dependency"><button onClick={()=>trace('ORG-439')}>IonPeak · qualified dies</button><span>Aster and Boreal retain the same SITE-074 die family.</span></div><div className="dependency"><button onClick={()=>trace('ORG-453')}>Jade · substrates</button><span>Cobalt, Grove and HarborSense retain SITE-081 substrates.</span></div><div className="dependency"><button onClick={()=>open({type:'entity',id:'ORG-455'})}>Umber · missing finance</button><span>P3 remains 69.8–85.5 until financial evidence is obtained.</span></div></Panel></div>
    <Panel title="Four-week pilot decision" detail="M1 · management proposal; illustrative economics, not a loss forecast" action={<button className="link-button" onClick={()=>navigate('Validation')}>Review gates →</button>}><div className="pilot-grid"><div><small>PILOT CEILING</small><strong>$150k</strong><span>$90k internal specialist · $30k samples · $10k dashboard · $20k contingency</span></div><div><small>ILLUSTRATIVE STRESS</small><strong>$5.5m</strong><span>One week of P1/P2 gross revenue equivalent at assumed 25% contribution margin; around 37× the pilot ceiling.</span></div></div><p className="footnote">The comparison frames a decision. It is not a measured loss, return on investment, or probability.</p></Panel>
    <p className="footnote">P3 is a screening index. Product revenue measures association, not expected loss.</p>
  </>;
}
function Network({filtered,focus,trace,setTrace,overlays,setOverlays,open}:{filtered:any[],focus:any,trace:string,setTrace:(v:string)=>void,overlays:any,setOverlays:(v:any)=>void,open:(v:any)=>void}){
  const visible=new Set(filtered.map(e=>e.id));
  const supply=data.links.filter((l:any)=>l.type==='Supply'&&l.status==='Confirmed'&&(!trace||l.source===trace||l.target===trace));
  const extras=data.links.filter((l:any)=>l.type==='Ownership'&&overlays.ownership||l.status==='Provisional'&&overlays.provisional);
  const shown=[...supply,...extras.filter((l:any)=>!trace||l.source===trace||l.target===trace)];
  return <><div className="toolbar"><Select label="Trace supplier" value={trace||'all'} onChange={v=>setTrace(v==='all'?'':v)} options={[{value:'all',label:'Full network'},...confirmed.map((e:any)=>({value:e.id,label:e.short+' · '+e.id}))]}/><label className="check"><input type="checkbox" checked={overlays.ownership} onChange={e=>setOverlays({...overlays,ownership:e.target.checked})}/>Ownership</label><label className="check"><input type="checkbox" checked={overlays.provisional} onChange={e=>setOverlays({...overlays,provisional:e.target.checked})}/>Provisional</label><label className="check"><input type="checkbox" checked={overlays.hypothesis} onChange={e=>setOverlays({...overlays,hypothesis:e.target.checked})}/>Sample hypotheses</label></div>
    {focus&&<div className="trace-card"><div><div className="eyebrow">SELECTED PATH</div><h2>{focus.name}</h2><p>Tier {focus.tier} · {focus.site} · {focus.zone} · {focus.capability}</p><div className="chip-row">{componentsFor(focus.id).map(c=><Pill key={c}>{c}</Pill>)}{focus.products.map((p:string)=><Pill key={p} tone="green">{p}</Pill>)}</div></div><button className="button" onClick={()=>open({type:'entity',id:focus.id})}>Open profile</button></div>}
    <Panel title="Programme path map" detail="Choose a manufacturer to trace inputs, allocated components and products"><div className="network-grid">{[3,2,1].map(t=><div className="tier" key={t}><div className="tier-head">TIER {t} <span>{filtered.filter(e=>e.tier===t).length}</span></div>{filtered.filter(e=>e.tier===t).map(e=><button key={e.id} className={'node '+(trace===e.id?'selected':'')} onClick={()=>setTrace(e.id)}><strong>{e.short}</strong><small>{e.site} · {e.zone}</small></button>)}</div>)}<div className="tier"><div className="tier-head">COMPONENTS</div>{data.components.map((c:any)=><div className="node static" key={c.id}><strong>{c.id}</strong><small>{c.name}</small></div>)}</div><div className="tier"><div className="tier-head">PRODUCTS</div>{data.products.map((p:any)=><div className="node static" key={p.id}><strong>{p.id}</strong><small>{p.name}</small></div>)}</div></div></Panel>
    <NetworkLayers overlays={overlays} open={open}/>
    <div className="two-cols"><Panel title="Relationship evidence" detail="29 confirmed entity links; component allocations are separate"><Table heads={['Supplier → customer','Input / status','Evidence']} rows={shown.filter((l:any)=>!trace||visible.has(l.source)||l.type==='Ownership').map((l:any)=>[<span>{entity(l.source)?.short||l.source} <b>→</b> {entity(l.target)?.short||l.target}</span>,<span>{l.input}<small>{l.status==='Confirmed'?'Confirmed':l.status}</small></span>,<button className="text-link" onClick={()=>open({type:'evidence',id:l.evidence[0]})}>{l.evidence.join(', ')}</button>])}/></Panel>
      <Panel title="Direct component allocations" detail="Planned award share; no claim about purchases or spare capacity"><Table heads={['Manufacturer','Component','Share','Evidence']} rows={data.allocations.filter((a:any)=>!trace||a.entity===trace).map((a:any)=>[<button className="text-link" onClick={()=>open({type:'entity',id:a.entity})}>{entity(a.entity)?.short}</button>,a.component,a.share+'%',<button className="text-link" onClick={()=>open({type:'evidence',id:a.evidence[0]})}>{a.evidence.join(', ')}</button>])}/></Panel></div>
    {overlays.hypothesis&&<div className="notice"><strong>Sample hypothesis · Solace</strong> — a possible relationship retained for investigation. It does not create a confirmed supply edge or change the manufacturer count.</div>}
    {overlays.provisional&&<div className="notice"><strong>Provisional · Verdant</strong> — the customer relationship remains unconfirmed and is excluded from the 29 confirmed supply links.</div>}
  </>;
}
function Risk({filtered,scenario,setScenario,allScenarios,open,openSource}:{filtered:any[],scenario:string,setScenario:(v:string)=>void,allScenarios:any,open:(v:any)=>void,openSource:(id:string)=>void}){
  const model=allScenarios[scenario]||scenarios.Base;
  const rows=filtered.map(e=>({e,s:score(e,scenario,model)}));const complete=rows.filter(x=>!x.s.missing).sort((a,b)=>b.s.P[0]-a.s.P[0]),missing=rows.filter(x=>x.s.missing).sort((a,b)=>b.s.P[0]-a.s.P[0]);
  return <><div className="formula-bar"><div><small>MODEL</small><strong>P3 · downstream path exposure</strong></div><Select label="Scenario" value={scenario} options={Object.keys(allScenarios)} onChange={setScenario}/><div><small>CONDITION · F/O/G</small><strong>{model.c.map((x:number)=>Math.round(x*100)).join(' / ')}%</strong></div><div><small>PRIORITY · C/B/S/E</small><strong>{model.p.map((x:number)=>Math.round(x*100)).join(' / ')}%</strong></div></div>
    <p className="explain">C = weighted financial, operating and geographic concern. P3 = weighted condition, product reach, switching constraint and downstream path exposure. E is the highest planned Tier-1 allocation reached through a confirmed path; it is not an upstream purchase share.</p>
    <Panel title="Complete-data manufacturers" detail="Ranked using unrounded values; displayed to one decimal" action={<button className="link-button" onClick={()=>openSource('A5')}>Scoring rules →</button>}><Table heads={['Manufacturer','C','B','S','E','P3','Workstream']} rows={complete.map(({e,s})=>[<button className="text-link" onClick={()=>open({type:'entity',id:e.id})}>{e.short}<small>Tier {e.tier} · {e.id}</small></button>,one(s.C[0]),one(s.B),s.S,s.E,<strong>{interval(s.P)}</strong>,<span>{s.band}{s.floor&&<small>Floor: {s.floor}</small>}</span>])}/></Panel>
    <Panel title="Missing financial inputs" detail="Intervals are not point estimates; five Tier-3 records require finance evidence"><Table heads={['Manufacturer','Condition range','P3 range','Confidence','Action']} rows={missing.map(({e,s})=>[<button className="text-link" onClick={()=>open({type:'entity',id:e.id})}>{e.short}</button>,interval(s.C),<strong>{interval(s.P)}</strong>,e.linkConfidence+' / '+e.indicatorConfidence,s.band])}/></Panel>
    <Panel title="Sensitivity" detail="Threshold crossings prompt review; the action floor applies in every scenario" action={<button className="link-button" onClick={()=>openSource('A6')}>Source table →</button>}><Table heads={['Manufacturer',...Object.keys(scenarios)]} rows={filtered.map(e=>[<button className="text-link" onClick={()=>open({type:'entity',id:e.id})}>{e.short}</button>,...Object.keys(scenarios).map(name=>interval(score(e,name).P))])}/></Panel>
    <div className="notice">Confidence grades describe evidence quality and do not change the score. U urgency describes the event, not the manufacturer. For Tier-3 missing finance, request dated financials, qualified capacity, actual supply site, inventory and recovery evidence before narrowing an interval.</div>
  </>;
}
function Alerts({records,open}:{records:RecordValue[],open:(v:any)=>void}){
  const ordered=[...data.events].sort((a:any,b:any)=>(urgency[a.id]==='U2'?0:urgency[a.id]==='U3'?1:2)-(urgency[b.id]==='U2'?0:urgency[b.id]==='U3'?1:2));
  return <><div className="metrics three"><div><small>Actionable reviews</small><strong>2 × U2</strong><span>Meridian and East Delta</span></div><div><small>Shipment check</small><strong>1 × U3</strong><span>Gulf Arc booking verification</span></div><div><small>Preserved exclusions</small><strong>5 × U0</strong><span>Duplicate, stale, admin, wrong entity</span></div></div><Panel title="Event triage" detail="Eight original event records; saved review state remains separate from source disposition"><Table heads={['Event / date','Match and disposition','Urgency','Review state','']} rows={ordered.map((e:any)=>{const saved=records.find(r=>r.kind==='alerts'&&r.eventId===e.id);return [<div><strong>{e.id}</strong><small>{e.published} · effective {e.effective}</small></div>,<div>{e.title}<small>{e.disposition}</small></div>,<Pill tone={urgency[e.id]==='U2'?'amber':urgency[e.id]==='U3'?'green':'neutral'}>{urgency[e.id]}</Pill>,saved?.status||'Not reviewed',<button className="text-link" onClick={()=>open({type:'alert',id:e.id})}>Inspect →</button>]})}/></Panel><div className="notice">Match precedence: exact entity/site ID, verified registry, corroborated legal name and role, curated alias, then geography. A conflicting higher-priority identity vetoes a similar name. U2 workstream clock: assign an owner within 24 hours, seek evidence within 72 hours, and make the pilot decision by Day 14.</div></>;
}
function Alternatives({route,setRoute,selected,setSelected,records,open,openSource}:{route:string,setRoute:(v:string)=>void,selected:string[],setSelected:(v:string[])=>void,records:RecordValue[],open:(v:any)=>void,openSource:(id:string)=>void}){
  const candidates=data.candidates.filter((c:any)=>c.route===route).sort((a:any,b:any)=>b.fit-a.fit);
  const choice=candidates.filter((c:any)=>selected.includes(c.id));const guide=data.routes.find((r:any)=>r.route===route);
  return <><div className="toolbar"><Select label="Supply form" value={route} options={routeNames} onChange={v=>{setRoute(v);setSelected([])}}/><button className="link-button" onClick={()=>openSource('M7')}>RFI and tie rules →</button></div><div className="route-card"><div><div className="eyebrow">REPLACEMENT SUPPLY FORM</div><h2>{route}</h2><p>{guide?.treatment||'Verify exact specification, supplying factory and programme fit.'}</p></div><div><small>FIRST STEP</small><strong>Parallel RFI where independence or site is unknown</strong></div></div><Panel title="Capability-screened candidates" detail="Fit is a diligence screen. Production approval needs eight evidence-backed gates."><Table heads={['Compare','Candidate','Fit','Assessment','Production']} rows={candidates.map((c:any)=>{const approval=records.find(r=>r.kind==='approvals'&&r.candidateId===c.id);return [<input type="checkbox" aria-label={'Compare '+c.name} checked={selected.includes(c.id)} onChange={e=>setSelected(e.target.checked?[...selected,c.id]:selected.filter(id=>id!==c.id))}/>,<button className="text-link" onClick={()=>open({type:'candidate',id:c.id})}>{c.name}<small>{route}</small></button>,<strong>{c.fit}</strong>,<Pill tone={c.fit>=75?'green':'neutral'}>{c.fit>=75?'Lead screen':c.fit>=65?'Co-shortlist':'Research reserve'}</Pill>,<span>{approval?.approved?'Approved':'Not approved'}<small><button className="text-link" onClick={()=>open({type:'candidate',id:c.id})}>Inspect gates →</button></small></span>]})}/></Panel>
    <Panel title={'Compare selected · '+choice.length} detail="Only candidates in this equivalent supply form appear together"><Table heads={['Dimension',...choice.map((c:any)=>c.name)]} rows={choice.length?[...['Technical match · 35%','Application · 25%','Footprint · 15%','Scale · 15%','Qualification support · 10%'].map((label,i)=>[label,...choice.map((c:any)=>c.ratings[i]+' / 5')]),['Total fit',...choice.map((c:any)=><strong>{c.fit}</strong>)],['Open questions',...choice.map((c:any)=>c.reason)]]:[]} empty="Select two or more candidates above to compare them."/></Panel>
    <Panel title="Full-component recovery routes" detail="M9 · seven component or common-input scopes requiring exact factory and qualification evidence" action={<button className="link-button" onClick={()=>openSource('M9')}>Source section →</button>}><Table heads={['Component / input','Screened recovery route','Verify before use']} rows={data.componentRoutes.map((r:any)=>[<strong>{r[0]}</strong>,r[1],r[2]])}/></Panel>
    <Panel title="Switching load before independence" detail="M6 · illustrative award-share multiples; nameplate or spare capacity has not been verified" action={<button className="link-button" onClick={()=>openSource('M6')}>Source section →</button>}><Table heads={['Reallocation','Award share','Required multiple','Constraint']} rows={data.switchMultiples.map((r:any)=>[r[0],r[1],<strong>{r[2]}</strong>,r[3]])}/></Panel>
    <div className="notice">A five-point fit gap may reflect one rating step. Where the gap is within five points, run parallel RFIs rather than treating the ranking as a sequence. Independence, eligible factory, supplier risk, capacity and qualification evidence determine the final route. Pilot RFI responses are due 14 October 2026. Coverage gap = required protected volume minus verified usable stock and confirmed recoverable supply; no award-share reallocation proves coverage.</div>
  </>;
}
function Actions({records,history,edit}:{records:RecordValue[],history:RecordValue[],edit:(v:any)=>void}){
  const actions=records.filter(r=>r.kind==='actions');if(!actions.some(a=>a.id===SEED_ACTION.id))actions.push(SEED_ACTION);
  return <><div className="toolbar"><button className="primary" onClick={()=>edit({id:crypto.randomUUID(),entityId:'',eventId:'',title:'',owner:'',dueDate:'',status:'Proposed',notes:'',closureEvidence:'',closureDate:''})}>+ New action</button><span className="muted">Saved ownership and history are held in the database.</span></div><Panel title="Continuity action register" detail="The Meridian record is a proposed starting action; supplier requests have not been sent"><Table heads={['Action','Owner / due','State','Updated','']} rows={actions.map(a=>[<span><strong>{a.title}</strong><small>{a.id} · {a.eventId||a.entityId||'Portfolio'}</small></span>,<span>{a.owner||'Unassigned'}<small>{a.dueDate||'Date open'}</small></span>,<Pill tone={a.status==='Closed'?'green':a.status==='Proposed'?'neutral':'amber'}>{a.status}</Pill>,a.updatedAt?new Date(a.updatedAt).toLocaleString():'Proposed seed',<button className="text-link" onClick={()=>edit(a)}>Open →</button>])}/></Panel><Panel title="Change history" detail="Each successful save creates a dated audit entry"><Table heads={['Time','Record','Actor']} rows={history.filter(h=>h.kind==='actions').map(h=>[new Date(h.created_at).toLocaleString(),h.payload.title||h.record_id,h.actor])} empty="No action changes saved yet."/></Panel></>;
}
function Evidence({records,save,open,openSource}:{records:RecordValue[],save:(k:string,p:any)=>Promise<any>,open:(v:any)=>void,openSource:(id:string)=>void}){
  const [tab,setTab]=useState('Case evidence'),[query,setQuery]=useState(''),[check,setCheck]=useState<RecordValue>({}),[draft,setDraft]=useState<RecordValue|null>(null),[err,setErr]=useState('');
  const sources=data.sources.filter((s:any)=>`${s.name} ${s.route} ${s.claim} ${s.links.map((l:any)=>l.url).join(' ')}`.toLowerCase().includes(query.toLowerCase()));
  const verify=async(url:string)=>{setErr('');try{const r=await fetch('/api/source',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const v=await r.json();setCheck({...check,[url]:v});if(!r.ok)setErr(v.note||v.error)}catch(e){setErr(changed(e))}};
  return <><div className="tabs">{['Case evidence','Public sources','Research log','Solution reference'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>{setTab(t);setQuery('')}}>{t}</button>)}</div><div className="toolbar"><input className="search wide" aria-label="Search evidence" placeholder="Search ID, supplier, source or route" value={query} onChange={e=>setQuery(e.target.value)}/></div>
    {tab==='Case evidence'&&<Panel title="Original case evidence" detail="59 records with exact source family, date, status and excerpt"><Table heads={['Record','Source / date','Status','']} rows={data.evidence.filter((e:any)=>`${e.id} ${e.title} ${e.detail} ${e.family}`.toLowerCase().includes(query.toLowerCase())).map((e:any)=>[<button className="text-link" onClick={()=>open({type:'evidence',id:e.id})}>{e.id}<small>{e.title}</small></button>,<span>{e.family}<small>{e.date}</small></span>,e.status,<button className="text-link" onClick={()=>open({type:'evidence',id:e.id})}>Read excerpt →</button>])}/></Panel>}
    {tab==='Public sources'&&<Panel title="Dated public source register" detail="Direct technical and financial links from 5 October 2026; live access is checked separately"><Table heads={['Source','Section','Access','']} rows={sources.flatMap((s:any)=>s.links.map((l:any)=>[<a className="external" href={l.url} target="_blank" rel="noreferrer">{l.title} ↗<small>{new URL(l.url).hostname} · {s.name}</small><small>{s.claim||'Capability source; programme approval remains open.'}</small></a>,s.section,<span>{check[l.url]?.access||records.find(r=>r.kind==='research'&&r.url===l.url)?.access||'Not rechecked'}<small>{check[l.url]?.checkedAt||'Source dated 5 Oct 2026'}</small></span>,<span className="inline-actions"><button className="text-link" onClick={()=>verify(l.url)}>Check</button><button className="text-link" onClick={()=>setDraft({id:crypto.randomUUID(),url:l.url,claim:s.claim||s.name+' '+s.route,owner:'',reason:'',disposition:'Under review',access:check[l.url]?.access||'Not rechecked',checkedAt:check[l.url]?.checkedAt||'',retrieved:'2026-10-05'})}>Assess</button></span>]))}/></Panel>}
    {tab==='Research log'&&<Panel title="Source assessments" detail="Supported claims and failed access checks remain visible"><Table heads={['Source / claim','Disposition','Access','Owner','']} rows={records.filter(r=>r.kind==='research').map(r=>[<a className="external" href={r.url} target="_blank" rel="noreferrer">{new URL(r.url).hostname} ↗<small>{r.claim}</small></a>,r.disposition,<span>{r.access}<small>{r.checkedAt||'Not rechecked'}</small></span>,r.owner,<button className="text-link" onClick={()=>setDraft(r)}>Edit →</button>])} empty="No source assessments saved yet."/></Panel>}
    {tab==='Solution reference'&&<Panel title="Final solution sections" detail="Open the original CONTENT.txt wording without loading the whole document into every screen"><div className="reference-list">{Object.entries(data.sections).filter(([id])=>/^[MA]\d+$/.test(id)).filter(([id,title])=>`${id} ${title}`.toLowerCase().includes(query.toLowerCase())).map(([id,title])=><button onClick={()=>openSource(id)} key={id}><strong>{id}</strong><span>{String(title)}</span><b>→</b></button>)}</div></Panel>}
    {err&&<div className="notice warning" role="alert">{err}</div>}
    {draft&&<Panel title="Review a source" detail="Keep the supported claim narrower than the linked evidence"><div className="form"><Field label="Official URL"><input value={draft.url} readOnly/></Field><Field label="Supported claim"><textarea value={draft.claim} onChange={e=>setDraft({...draft,claim:e.target.value})}/></Field><div className="form-grid"><Field label="Owner"><input value={draft.owner} onChange={e=>setDraft({...draft,owner:e.target.value})}/></Field><Field label="Disposition"><Select label="Disposition" value={draft.disposition} options={['Under review','Accepted','Rejected']} onChange={v=>setDraft({...draft,disposition:v})}/></Field></div><Field label="Reason and limitations"><textarea value={draft.reason} onChange={e=>setDraft({...draft,reason:e.target.value})}/></Field><div className="inline-actions"><button className="primary" onClick={async()=>{try{setDraft(await save('research',draft));setDraft(null);setTab('Research log')}catch(e){setErr(changed(e))}}}>Save assessment</button><button className="button" onClick={()=>setDraft(null)}>Cancel</button></div></div></Panel>}
  </>;
}
function Validation({records,history,save,openSource}:{records:RecordValue[],history:RecordValue[],save:(k:string,p:any)=>Promise<any>,openSource:(id:string)=>void}){
  const [tab,setTab]=useState('Acceptance'),[test,setTest]=useState<RecordValue|null>(null),[model,setModel]=useState<RecordValue>({name:'',rationale:'',c:[35,35,30],p:[45,25,20,10]}),[err,setErr]=useState('');
  const result=(data.tests as any[]).map(t=>({...t,...records.find(r=>r.kind==='validation'&&r.id===t.id)}));const pass=result.filter(r=>r.status==='PASS').length;
  return <><div className="tabs">{['Acceptance','Model history','Audit history'].map(t=><button className={tab===t?'active':''} onClick={()=>setTab(t)} key={t}>{t}</button>)}</div>
    {tab==='Acceptance'&&<><Panel title={'Observed acceptance · '+pass+' / 25 passed'} detail="Source expectations are separate from observed results; record tests after using this deployment"><Table heads={['Test','Expected','Observed result','']} rows={result.map(r=>[<span><strong>{r.id} · {r.name}</strong></span>,r.expected,<span>{r.status||'NOT EXECUTED'}<small>{r.observed||'No observed value recorded'}</small></span>,<button className="text-link" onClick={()=>setTest({id:r.id,status:r.status||'NOT EXECUTED',build:r.build||'P3.0',tester:r.tester||'',date:r.date||'',observed:r.observed||'',evidence:r.evidence||'',failureAction:r.failureAction||'',revision:r.revision||0})}>Record →</button>])}/></Panel>{test&&<Panel title={'Acceptance test '+test.id} detail={data.tests.find((t:any)=>t.id===test.id)?.expected}><div className="form"><div className="form-grid"><Field label="Result"><Select label="Test result" value={test.status} options={['NOT EXECUTED','PASS','FAIL']} onChange={v=>setTest({...test,status:v})}/></Field><Field label="Tester"><input value={test.tester} onChange={e=>setTest({...test,tester:e.target.value})}/></Field><Field label="Execution date and time"><input type="datetime-local" value={test.date} onChange={e=>setTest({...test,date:e.target.value})}/></Field><Field label="Build"><input value={test.build} onChange={e=>setTest({...test,build:e.target.value})}/></Field></div><Field label="Observed value"><textarea value={test.observed} onChange={e=>setTest({...test,observed:e.target.value})}/></Field><Field label="Screenshot or record ID"><input value={test.evidence} onChange={e=>setTest({...test,evidence:e.target.value})}/></Field><Field label="Defect owner and due date, if failed"><input value={test.failureAction} onChange={e=>setTest({...test,failureAction:e.target.value})}/></Field><div className="inline-actions"><button className="primary" onClick={async()=>{try{await save('validation',test);setTest(null)}catch(e){setErr(changed(e))}}}>Save observation</button><button className="button" onClick={()=>setTest(null)}>Cancel</button></div></div></Panel>}</>}
    {tab==='Model history'&&<><Panel title="Current and prior models" detail="P3 values are current; P2 remains historical"><Table heads={['Version','Condition F/O/G','Priority terms','Rationale']} rows={[[<strong>P3 · downstream path exposure</strong>,'35 / 35 / 30','C/B/S/E 45 / 25 / 20 / 10','Current; E measures downstream path exposure and action floor applies.'],['P2 · path aware (historical)','35 / 35 / 30','C/B/S 45 / 35 / 20','Prior model retained for comparison only.'],...records.filter(r=>r.kind==='models').map(r=>[r.name,r.c.map((n:number)=>Math.round(n*100)).join(' / '),r.p.map((n:number)=>Math.round(n*100)).join(' / '),r.rationale])]}/><button className="link-button inline-pad" onClick={()=>openSource('M3')}>Read scorecard definition →</button></Panel><Panel title="Historic P2 score register" detail="Historical values are visible only in model history; current decisions use P3"><Table heads={['Manufacturer','Historic P2','Current P3']} rows={confirmed.map((e:any)=>[e.short,interval(scoreP2(e)),interval(score(e).P)])}/></Panel><Panel title="Save an alternate model version" detail="New versions are immutable and named; the P3 baseline stays unchanged"><div className="form"><Field label="Version name"><input value={model.name} onChange={e=>setModel({...model,name:e.target.value})}/></Field><div className="form-grid"><div><h3>Condition weights · %</h3><div className="weight-grid">{['F','O','G'].map((name,i)=><Field key={name} label={name}><input type="number" min="0" max="100" value={model.c[i]} onChange={e=>setModel({...model,c:model.c.map((n:number,j:number)=>j===i?Number(e.target.value):n)})}/></Field>)}</div></div><div><h3>Priority weights · %</h3><div className="weight-grid">{['C','B','S','E'].map((name,i)=><Field key={name} label={name}><input type="number" min="0" max="100" value={model.p[i]} onChange={e=>setModel({...model,p:model.p.map((n:number,j:number)=>j===i?Number(e.target.value):n)})}/></Field>)}</div></div></div><Field label="Reason for revision"><textarea value={model.rationale} onChange={e=>setModel({...model,rationale:e.target.value})}/></Field><button className="primary" onClick={async()=>{try{await save('models',{id:crypto.randomUUID(),name:model.name,rationale:model.rationale,c:model.c.map((n:number)=>n/100),p:model.p.map((n:number)=>n/100)});setModel({...model,name:'',rationale:''})}catch(e){setErr(changed(e))}}}>Save model version</button></div></Panel></>}
    {tab==='Audit history'&&<Panel title="Saved workspace history" detail="Actions, alerts, qualification, research, models and validation"><Table heads={['When','Record type','Record','Actor']} rows={history.map(h=>[new Date(h.created_at).toLocaleString(),h.kind,h.payload.title||h.payload.name||h.payload.id,h.actor])} empty="No changes saved yet."/></Panel>}
    {err&&<div className="notice warning" role="alert">{err}</div>}
  </>;
}
function Detail({item,close,setDetail,records,save,createAction,trace,route}:{item:{type:string,id:string},close:()=>void,setDetail:(v:any)=>void,records:RecordValue[],save:(k:string,p:any)=>Promise<any>,createAction:(v:any)=>void,trace:(v:string)=>void,route:(v:string)=>void}){
  const [err,setErr]=useState(''),[busy,setBusy]=useState(false);
  const event=data.events.find((e:any)=>e.id===item.id),supplier=entity(item.id),evidence=data.evidence.find((e:any)=>e.id===item.id),candidate=data.candidates.find((c:any)=>c.id===item.id);
  const prior=records.find(r=>r.kind==='alerts'&&r.eventId===item.id);
  const [review,setReview]=useState<RecordValue>(prior||{id:'ALERT-'+item.id,eventId:item.id,status:'New',owner:'',dueDate:'',decision:'',closureEvidence:'',closureDate:''});
  const previous=records.find(r=>r.kind==='approvals'&&r.candidateId===item.id);
  const [approval,setApproval]=useState<RecordValue>(previous||{id:'APP-'+item.id,candidateId:item.id,gates:Object.fromEntries(GATES.map(g=>[g,{status:'Not started',evidence:'',date:''}])),factory:'',programme:'',volume:'',approver:'',validUntil:'',approved:false});
  const s=supplier?.tier?score(supplier):null;
  const relatedEvidence=supplier?data.evidence.filter((x:any)=>x.detail.includes(supplier.name)||x.title.includes(supplier.name)).slice(0,20):[];
  const candidateSources=candidate?data.sources.filter((x:any)=>x.name.toLowerCase()===candidate.name.toLowerCase()||(candidate.name!=='ST'&&x.name.toLowerCase().split(/\s*\/\s*/).includes(candidate.name.toLowerCase()))).slice(0,8):[];
  const saveIt=async(kind:string,p:any)=>{setBusy(true);setErr('');try{const v=await save(kind,p);if(kind==='alerts')setReview(v);else setApproval(v)}catch(e){setErr(changed(e))}finally{setBusy(false)}};
  return <div className="drawer-backdrop" onClick={close}><aside className="drawer" role="dialog" aria-modal="true" aria-label="Record detail" onClick={e=>e.stopPropagation()} key={item.type+item.id}><div className="drawer-top"><span>{item.type==='entity'?'MANUFACTURER PROFILE':item.type==='alert'?'EVENT REVIEW':item.type==='candidate'?'CANDIDATE ASSESSMENT':'ORIGINAL CASE EVIDENCE'}</span><button aria-label="Close detail" onClick={close}>×</button></div>
    {supplier&&<><div className="chip-row"><Pill>Tier {supplier.tier||'—'}</Pill><Pill tone={supplier.zone==='Z01'?'amber':'neutral'}>{supplier.zone}</Pill><Pill>{supplier.status}</Pill></div><h2>{supplier.name}</h2><p className="drawer-lead">{supplier.capability}. Manufacturing: {supplier.site} · {supplier.siteName}. Registered zone: {supplier.registeredZone}.</p>{s&&<><div className="drawer-metrics"><div><small>CONDITION</small><strong>{interval(s.C)}</strong></div><div><small>P3 SCREEN</small><strong>{interval(s.P)}</strong></div></div><div className="notice">{s.band}. {s.floor||'No mandatory action floor.'} Confidence: link {supplier.linkConfidence} / indicators {supplier.indicatorConfidence}.</div><dl className="facts"><dt>Products</dt><dd>{supplier.products.join(' / ')}</dd><dt>Components</dt><dd>{componentsFor(supplier.id).join(' / ')}</dd><dt>Financial concern</dt><dd>{s.F===null?'Missing · range 0–100':one(s.F)}</dd><dt>Operating / geography</dt><dd>{one(s.O)} / {one(s.G)}</dd><dt>Business reach B</dt><dd>{one(s.B)} · ${s.revenue}m associated revenue</dd><dt>Switching S / path E</dt><dd>{s.S} / {s.E}</dd></dl><IndicatorBreakdown supplier={supplier}/><p className="muted">E is the maximum disclosed downstream Tier-1 allocation on a confirmed path. It is not this upstream supplier’s share of purchases.</p></>}{supplier.note&&<p>{supplier.note}</p>}<div className="inline-actions"><button className="primary" onClick={()=>trace(supplier.id)}>Trace path</button><button className="button" onClick={()=>createAction({id:crypto.randomUUID(),entityId:supplier.id,eventId:'',title:'Verify '+supplier.short+' continuity and independent recovery',owner:'',dueDate:'',status:'Proposed',notes:'',closureEvidence:'',closureDate:''})}>Create action</button></div><h3>Original case evidence</h3><div className="record-list">{relatedEvidence.map((x:any)=><button key={x.id} onClick={()=>setDetail({type:'evidence',id:x.id})}><strong>{x.id}</strong><span>{x.title}</span></button>)}</div></>}
    {evidence&&<><Pill>{evidence.id}</Pill><h2>{evidence.title}</h2><p className="drawer-lead">{evidence.detail}</p><dl className="facts"><dt>Source family</dt><dd>{evidence.family}</dd><dt>Publication</dt><dd>{evidence.date}</dd><dt>Status</dt><dd>{evidence.status}</dd><dt>Original locator</dt><dd>{evidence.locator}</dd></dl><div className="notice">This is fictional case evidence; its synthetic locator is not a public website.</div></>}
    {event&&<><div className="chip-row"><Pill tone={urgency[event.id]==='U2'?'amber':'neutral'}>{urgency[event.id]}</Pill><Pill>{event.disposition}</Pill></div><h2>{event.id} · {event.title}</h2><p className="drawer-lead">{event.detail}</p><dl className="facts"><dt>Published</dt><dd>{event.published}</dd><dt>Effective</dt><dd>{event.effective}</dd><dt>Source family</dt><dd>{event.family}</dd><dt>Resolution</dt><dd>{event.disposition}</dd></dl>{event.id==='EV-003'&&<><div className="notice">Meridian ORG-210 / SITE-102 → Delta → C20 → P1/P2. $1,144m annual product association. Meridian C 74.1; P3 76.7.</div><div className="inline-actions"><button className="button" onClick={()=>setDetail({type:'evidence',id:'DOC-039'})}>Open DOC-039</button><button className="button" onClick={()=>trace('ORG-210')}>Trace route</button><button className="button" onClick={()=>route('Metallised film')}>Compare film routes</button></div></>}{event.id==='EV-001'&&<div className="notice">Verify SITE-074, SITE-081, SITE-116 and SITE-158 separately. No confirmed shutdown.</div>}{event.id==='EV-002'&&<div className="notice">Same WX-0923 incident as EV-001; retain this record without creating a second production alert.</div>}{event.id==='EV-004'&&<div className="notice">REG-NO-4128 identifies Ion Peak Trading, a broker. Excluded from IonPeak manufacturing.</div>}{event.id==='EV-010'&&<div className="notice">U3 until a booking-specific usable-coverage gap is evidenced. Illustrative method: approved C20 shipment arrival Day 4 → Day 7, usable coverage through Day 6, so one uncovered day. P1/P2 association is $1,144m annually, or $22m per 52-week year; $3.14m is a seven-day gross daily equivalent, not observed impact. Verify booking, quantity, BOM demand, customs and accessible inventory.</div>}
      <h3>Save event review</h3><div className="form"><div className="form-grid"><Field label="Review status"><Select label="Review status" value={review.status} options={['New','Verifying','Action agreed','Monitoring','Closed','Reopened']} onChange={v=>setReview({...review,status:v})}/></Field><Field label="Owner"><input value={review.owner} onChange={e=>setReview({...review,owner:e.target.value})}/></Field><Field label="Evidence due"><input type="date" value={review.dueDate} onChange={e=>setReview({...review,dueDate:e.target.value})}/></Field></div><Field label="Decision and evidence needed"><textarea value={review.decision} onChange={e=>setReview({...review,decision:e.target.value})}/></Field>{review.status==='Closed'&&<div className="form-grid"><Field label="Closure evidence"><input value={review.closureEvidence} onChange={e=>setReview({...review,closureEvidence:e.target.value})}/></Field><Field label="Evidence date"><input type="date" value={review.closureDate} onChange={e=>setReview({...review,closureDate:e.target.value})}/></Field></div>}<div className="inline-actions"><button className="primary" disabled={busy} onClick={()=>saveIt('alerts',review)}>Save review</button><button className="button" onClick={()=>createAction({...(event.id==='EV-003'?SEED_ACTION:{id:crypto.randomUUID(),entityId:'',eventId:event.id,title:'Verify '+event.title,owner:'',dueDate:'',status:'Proposed',notes:'',closureEvidence:'',closureDate:''})})}>Create linked action</button></div></div></>}
    {candidate&&<><div className="chip-row"><Pill>{candidate.route}</Pill><Pill tone={candidate.fit>=75?'green':'neutral'}>Fit {candidate.fit}</Pill></div><h2>{candidate.name}</h2><p className="drawer-lead">{candidate.reason}</p><div className="notice">Fit is a capability screen. The factory, technical compatibility, committed capacity, independent inputs and NovaDrive qualification remain open.</div><h3>Fit dimensions</h3><Table heads={['Dimension','Rating','Points']} rows={['Technical · 35','Application · 25','Footprint · 15','Scale · 15','Qualification · 10'].map((n,i)=>[n,candidate.ratings[i]+' / 5',one(candidate.ratings[i]*[35,25,15,15,10][i]/5)])}/><h3>Direct source links</h3><div className="record-list">{candidateSources.flatMap((s:any)=>s.links.map((l:any,i:number)=><a className="external" href={l.url} key={s.id+'-'+i} target="_blank" rel="noreferrer">{l.title} ↗<small>{s.section} · {s.claim||s.route||s.name}</small></a>))}</div><h3>Qualification and independence gates</h3><p className="muted">A passed gate requires an evidence reference and date. Approval also needs a specific factory, programme, volume, approver and validity.</p>{GATES.map(g=><div className="gate" key={g}><div className="gate-head"><strong>{g}</strong><Select label={g+' gate status'} value={approval.gates[g].status} options={['Not started','Evidence requested','Under review','Passed','Failed']} onChange={v=>setApproval({...approval,approved:false,gates:{...approval.gates,[g]:{...approval.gates[g],status:v}}})}/></div><div className="form-grid"><Field label={g+' evidence'}><input value={approval.gates[g].evidence} onChange={e=>setApproval({...approval,approved:false,gates:{...approval.gates,[g]:{...approval.gates[g],evidence:e.target.value}}})}/></Field><Field label={g+' date'}><input type="date" value={approval.gates[g].date} onChange={e=>setApproval({...approval,approved:false,gates:{...approval.gates,[g]:{...approval.gates[g],date:e.target.value}}})}/></Field></div></div>)}<div className="form-grid">{[['factory','Approved factory / process'],['programme','Programme and component'],['volume','Approved volume'],['approver','Approver']].map(([key,label])=><Field label={label} key={key}><input value={approval[key]} onChange={e=>setApproval({...approval,[key]:e.target.value})}/></Field>)}<Field label="Approval valid until"><input type="date" value={approval.validUntil} onChange={e=>setApproval({...approval,validUntil:e.target.value})}/></Field></div><label className="check approval-check"><input type="checkbox" checked={approval.approved} onChange={e=>setApproval({...approval,approved:e.target.checked})}/>Record production approval</label><button className="primary" disabled={busy} onClick={()=>saveIt('approvals',approval)}>Save qualification review</button></>}
    {err&&<p className="error" role="alert">{err}</p>}
  </aside></div>;
}
function ActionDialog({draft,close,save}:{draft:RecordValue,close:()=>void,save:(k:string,p:any)=>Promise<any>}){
  const [value,setValue]=useState(draft),[err,setErr]=useState(''),[busy,setBusy]=useState(false);
  return <div className="drawer-backdrop" onClick={close}><div className="action-modal" role="dialog" aria-modal="true" aria-label="Edit action" onClick={e=>e.stopPropagation()}><div className="drawer-top"><span>CONTINUITY ACTION</span><button aria-label="Close action" onClick={close}>×</button></div><h2>{value.id==='ACT-MERIDIAN'?'Meridian continuity action':'Action record'}</h2><div className="form"><Field label="Action"><textarea value={value.title} onChange={e=>setValue({...value,title:e.target.value})}/></Field><div className="form-grid"><Field label="Owner"><input value={value.owner} onChange={e=>setValue({...value,owner:e.target.value})}/></Field><Field label="Due date"><input type="date" value={value.dueDate} onChange={e=>setValue({...value,dueDate:e.target.value})}/></Field><Field label="Status"><Select label="Action status" value={value.status} options={ACTION_STATES} onChange={v=>setValue({...value,status:v})}/></Field></div><Field label="Evidence, next step and limitations"><textarea value={value.notes} onChange={e=>setValue({...value,notes:e.target.value})}/></Field>{value.status==='Closed'&&<div className="form-grid"><Field label="Closure evidence"><input value={value.closureEvidence} onChange={e=>setValue({...value,closureEvidence:e.target.value})}/></Field><Field label="Evidence date"><input type="date" value={value.closureDate} onChange={e=>setValue({...value,closureDate:e.target.value})}/></Field></div>}{err&&<p className="error" role="alert">{err}</p>}<div className="inline-actions"><button className="primary" disabled={busy} onClick={async()=>{setBusy(true);setErr('');try{await save('actions',value);close()}catch(e){setErr(changed(e))}finally{setBusy(false)}}}>Save action</button><button className="button" onClick={close}>Cancel</button></div></div></div></div>;
}
